public String AndroidThunkJava_OpenMobileDeviceGetDisplayName()
{
	CharSequence label = getPackageManager().getApplicationLabel(getApplicationInfo());
	return label == null ? "" : label.toString();
}

public String AndroidThunkJava_OpenMobileDeviceGetPackageIdentifier()
{
	return getPackageName();
}

private android.content.pm.PackageInfo AndroidThunkJava_OpenMobileDeviceGetPackageInfo()
{
	try
	{
		return getPackageManager().getPackageInfo(getPackageName(), 0);
	}
	catch (android.content.pm.PackageManager.NameNotFoundException ignored)
	{
		return null;
	}
}

public String AndroidThunkJava_OpenMobileDeviceGetVersionName()
{
	android.content.pm.PackageInfo packageInfo = AndroidThunkJava_OpenMobileDeviceGetPackageInfo();
	return packageInfo == null || packageInfo.versionName == null ? "" : packageInfo.versionName;
}

public String AndroidThunkJava_OpenMobileDeviceGetBuildNumber()
{
	android.content.pm.PackageInfo packageInfo = AndroidThunkJava_OpenMobileDeviceGetPackageInfo();
	if (packageInfo == null)
	{
		return "";
	}
	return android.os.Build.VERSION.SDK_INT >= 28
		? Long.toString(packageInfo.getLongVersionCode())
		: Integer.toString(packageInfo.versionCode);
}

public String[] AndroidThunkJava_OpenMobileDeviceGetPreferredLanguages()
{
	android.content.res.Configuration configuration = getResources().getConfiguration();
	if (android.os.Build.VERSION.SDK_INT >= 24)
	{
		android.os.LocaleList locales = configuration.getLocales();
		String[] languages = new String[locales.size()];
		for (int index = 0; index < locales.size(); ++index)
		{
			languages[index] = locales.get(index).toLanguageTag();
		}
		return languages;
	}
	return configuration.locale == null
		? new String[0]
		: new String[] { configuration.locale.toLanguageTag() };
}

public String[] AndroidThunkJava_OpenMobileDeviceGetLocaleDetails()
{
	android.content.res.Configuration configuration = getResources().getConfiguration();
	java.util.Locale locale = android.os.Build.VERSION.SDK_INT >= 24
		? configuration.getLocales().get(0)
		: configuration.locale;
	if (locale == null)
	{
		return new String[0];
	}
	String currencyCode = "";
	try
	{
		java.util.Currency currency = java.util.Currency.getInstance(locale);
		currencyCode = currency == null ? "" : currency.getCurrencyCode();
	}
	catch (IllegalArgumentException ignored)
	{
	}
	return new String[] {
		locale.toLanguageTag(),
		locale.getLanguage(),
		locale.getScript(),
		locale.getCountry(),
		currencyCode
	};
}
